struct vector4d
{
	float x, y, z, w;
};

struct po
{
	vector4d m[4];
};

class stringx
{
	char *chars;
	void *my_buf;
};

class entity;

struct link_interface
{
	char pad0[8];
	link_interface *parent;
	char pad1[68];
	po abs_po;

	void update_abs_po_family();
};

struct entity_vtable
{
	char pad0[64];
	short adjustment;
	short reserved;
	void (*po_changed)(void *);
};

class entity_anim_tree
{
	char pad0[88];
	float tween_duration;

public:
	void frame_advance(float time);
	void set_tween_duration(float duration) { tween_duration = duration; }
};

class entity
{
	char pad0[8];
	entity_vtable *vtable;
	po rel_po;
	char pad1[24];
	link_interface *link;

public:
	entity_anim_tree *get_anim_tree(int channel) const;
	entity_anim_tree *play_anim(int channel, const stringx &filename,
	                           float start_time, unsigned short anim_flags = 0,
	                           short loop = -1);

	void set_rel_po(const po &value)
	{
		rel_po = value;
		if (link)
		{
			if (link->parent)
			{
				const po &p = link->parent->abs_po;
				const po &r = rel_po;
				po &a = link->abs_po;
				for (int i = 0; i != 4; ++i)
				{
					a.m[i].x = p.m[0].x*r.m[i].x + p.m[1].x*r.m[i].y + p.m[2].x*r.m[i].z;
					a.m[i].y = p.m[0].y*r.m[i].x + p.m[1].y*r.m[i].y + p.m[2].y*r.m[i].z;
					a.m[i].z = p.m[0].z*r.m[i].x + p.m[1].z*r.m[i].y + p.m[2].z*r.m[i].z;
					a.m[i].w = p.m[0].w*r.m[i].x + p.m[1].w*r.m[i].y + p.m[2].w*r.m[i].z + p.m[3].w*r.m[i].w;
				}
				a.m[0].w = a.m[1].w = a.m[2].w = 0.0f;
				a.m[3].w = 1.0f;
			}
			else
				link->abs_po = rel_po;
			link->update_abs_po_family();
		}
		entity_vtable *table = vtable;
		table->po_changed((char *)this + table->adjustment);
	}
};

extern stringx g_board_anims[];
extern const po po_identity_matrix;

enum
{
	ANIM_PRIMARY,
	ANIM_LOOPING = 0x4,
	ANIM_TWEEN = 0x800,
	ANIM_NONCOSMETIC = 0x200,
	BOARD_ANIM_ZERO = 0
};

class FEEntityManager
{
	char pad0[404];
	entity *board;
	char pad1[28];
	entity_anim_tree *board_tree;

public:
	void BoardAnim(int anim_id, float blend_time, bool loop, float time);
};

__asm__(".equ g_board_anims, 0x00422640");
__asm__(".equ po_identity_matrix, 0x00513CD0");
__asm__(".equ get_anim_tree__C6entityi, 0x001348D8");
__asm__(".equ play_anim__6entityiRC7stringxfUss, 0x00133E60");
__asm__(".equ frame_advance__16entity_anim_treef, 0x001177F0");
__asm__(".equ update_abs_po_family__14link_interface, 0x00122198");

void FEEntityManager::BoardAnim(int anim_id, float blend_time, bool loop, float time )
{
	board_tree = board->get_anim_tree(ANIM_PRIMARY);
	bool no_tween = false;

	if (anim_id == BOARD_ANIM_ZERO)
	  board->set_rel_po(po_identity_matrix);

	no_tween = !board_tree || (blend_time == 0.0f);

	if(time > 0.0f)
	{
		board_tree = board->play_anim(ANIM_PRIMARY, g_board_anims[anim_id], time, (loop ? ANIM_LOOPING : 0) | (no_tween ? 0 : ANIM_TWEEN) | ANIM_NONCOSMETIC);
		board_tree->frame_advance(0.0f);
	}
	else
	{
		board_tree = board->play_anim(ANIM_PRIMARY, g_board_anims[anim_id], 0.0f, (loop ? ANIM_LOOPING : 0) | (no_tween ? 0 : ANIM_TWEEN) | ANIM_NONCOSMETIC);
		if (!no_tween)
			board_tree->set_tween_duration(blend_time);
	}
}
